@Test
public void testPattern() throws ParseException {
    /*
         * Condition: YYYY(?:.MM|MM)?(?:.DD|DD)?(?:.hh|hh)?(?:.mm|mm)?(?:.ss|ss)? The date expression as a whole must
         * meet this condition in order to match Need to start with YYYY, and month, day, hour, minute can only be
         * separated by one character
         */
    testReplaceDateExpression("/YYYYMMDDhhmm.log", "/202406251007.log");
    testReplaceDateExpression("/YYYY.log", "/2024.log");
    testReplaceDateExpression("/YYYYhhmm.log", "/20241007.log");
    testReplaceDateExpression("/YYYY/YYYYMMDDhhmm.log", "/2024/202406251007.log");
    testReplaceDateExpression("/YYYY/MMDD/hhmm.log", "/2024/0625/1007.log");
    testReplaceDateExpression("/data/YYYYMMDD.hh/mm.log_[0-9]+", "/data/20240625.10/07.log_[0-9]+");
    // error cases
    testReplaceDateExpression("/YYY.log", "/YYY.log");
    testReplaceDateExpression("/MMDDhhmm.log", "/MMDDhhmm.log");
    testReplaceDateExpression("/MMDD/hhmm.log", "/MMDD/hhmm.log");
    testReplaceDateExpression("/data/YYYYMMDD..hh/mm.log_[0-9]+", "/data/20240625..hh/mm.log_[0-9]+");
    /*
         * 1 cut the file name 2 cut the path contains wildcard
         */
    testCutDirectoryByWildcard("/data/123/YYYYMMDDhhmm.log", Arrays.asList("/data/123", "", "YYYYMMDDhhmm.log"));
    testCutDirectoryByWildcard("/data/YYYYMMDDhhmm/test.log", Arrays.asList("/data/YYYYMMDDhhmm", "", "test.log"));
    testCutDirectoryByWildcard("/data/YYYYMMDDhhmm*/test.log", Arrays.asList("/data", "YYYYMMDDhhmm*", "test.log"));
    testCutDirectoryByWildcard("/data/log_minute/minute_YYYYMMDDhh*/mm.log_[0-9]+", Arrays.asList("/data/log_minute", "minute_YYYYMMDDhh*", "mm.log_[0-9]+"));
    testCutDirectoryByWildcard("/data/123+/YYYYMMDDhhmm.log", Arrays.asList("/data", "123+", "YYYYMMDDhhmm.log"));
    testCutDirectoryByWildcard("/data/2024112610*/test.log", Arrays.asList("/data", "2024112610*", "test.log"));
    /*
         * 1 cut the file name 2 cut the path contains wildcard or date expression
         */
    testCutDirectoryByWildcardAndDateExpression("/data/YYYYMM/YYYaaMM/YYYYMMDDhhmm.log", Arrays.asList("/data", "YYYYMM/YYYaaMM", "YYYYMMDDhhmm.log"));
    testCutDirectoryByWildcardAndDateExpression("/data/YYYY/test.log", Arrays.asList("/data", "YYYY", "test.log"));
    testCutDirectoryByWildcardAndDateExpression("/data/123*/MMDD/test.log", Arrays.asList("/data", "123*/MMDD", "test.log"));
    testCutDirectoryByWildcardAndDateExpression("/data/YYYYMMDD/123*/test.log", Arrays.asList("/data", "YYYYMMDD/123*", "test.log"));
    /*
         * get the string before the first wildcard
         */
    testGetBeforeFirstWildcard("/data/YYYYMM/YYYaaMM/YYYYMMDDhhmm.log", "/data/YYYYMM/YYYaaMM/YYYYMMDDhhmm");
    testGetBeforeFirstWildcard("/data/123*/MMDD/test.log", "/data/123");
    testGetBeforeFirstWildcard("/data/YYYYMMDD/123*/test.log", "/data/YYYYMMDD/123");
    testGetBeforeFirstWildcard("test/65535_YYYYMMDD_hh00.log", "test/65535_YYYYMMDD_hh00");
    testGetBeforeFirstWildcard("/data/YYYYMMDD/*123/test.log", "/data/YYYYMMDD/");
}

