    Assert.assertThrows(ProxyEventException.class, () -> new TcpEventInfo(groupId, streamId, dtMs, attrsA1, bodyA301));
    byte[] bodyA302 = "".getBytes(StandardCharsets.UTF_8);
    Assert.assertThrows(ProxyEventException.class, () -> new TcpEventInfo(groupId, streamId, dtMs, attrsA1, bodyA302));
    byte[] bodyA303 = "    ".getBytes(StandardCharsets.UTF_8);
