    Assert.assertThrows(ProxyEventException.class, () -> new TcpEventInfo(groupId, streamId, dtMs, attrsA1, msgListA311));
    List<byte[]> msgListA312 = new ArrayList<>();
    Assert.assertThrows(ProxyEventException.class, () -> new TcpEventInfo(groupId, streamId, dtMs, attrsA1, msgListA312));
    List<byte[]> msgListA313 = new ArrayList<>();
