    TransformProcessor<String, String> processor3 = TransformProcessor.create(config3, SourceDecoderFactory.createCsvDecoder(csvSource), SinkEncoderFactory.createKvEncoder(kvSink));
    // case: least(1, least(-2, -5), least(3.14836, 8))
