    String data = "  CREATe TABLE `table_1`(
" + "    `age` INT,
" + "    `name` STRING)
" + "    WITH (
" + "    'connector' = 'mysql-cdc-inlong',
" + "    'hostname' = 'localhost',
" + "    'username' = 'root',
" + "    'password' = 'inlong',
" + "    'database-name' = 'test',
" + "    'scan.incremental.snapshot.enabled' = 'false',
" + "    'server-time-zone' = 'GMT+8',
" + "    'table-name' = 'user',
" + "    'port' = '3306'
" + ");
" + "CREATE TABLE `table_2`(
" + "    PRIMARY KEY (`name`,`age`) NOT ENFORCED,
" + "    `name` STRING,
" + "    `age` INT)
" + "    WITH (
" + "    'connector' = 'jdbc',
" + "    'url' = 'jdbc:postgresql://localhost:5432/postgres',
" + "    'username' = 'postgres',
" + "    'password' = 'inlong',
" + "    'table-name' = 'public.user'
