@Test
public void testKafkaToElasticsearch() throws Exception {
    submitSQLJob(sqlFile, kafkaJar, elasticsearchJar);
    waitUntilJobRunning(Duration.ofSeconds(10));
    // Produce messages to Kafka
    org.apache.kafka.clients.producer.KafkaProducer<String, String> producer = new org.apache.kafka.clients.producer.KafkaProducer<>(getKafkaProducerConfig());
    producer.send(new org.apache.kafka.clients.producer.ProducerRecord<>("test-topic", "key1", FIRST_KAFKA_MESSAGE));
    producer.send(new org.apache.kafka.clients.producer.ProducerRecord<>("test-topic", "key2", SECOND_KAFKA_MESSAGE));
    // Query Elasticsearch to verify data is ingested
    RestClient restClient = RestClient.builder(new HttpHost("localhost", ELASTICSEARCH.getMappedPort(9200), "http")).build();
    RestClientTransport transport = new RestClientTransport(restClient, new JacksonJsonpMapper());
    ElasticsearchClient client = new ElasticsearchClient(transport);
    List<String> messages = new ArrayList<>();
    // Maximum number of retries (10 seconds)
    int maxRetries = 10;
    int retryCount = 0;
    while (retryCount < maxRetries) {
        co.elastic.clients.elasticsearch.core.SearchRequest searchRequest = new co.elastic.clients.elasticsearch.core.SearchRequest.Builder().index("test-index").query(q -> q.matchAll(m -> m)).build();
        co.elastic.clients.elasticsearch.core.SearchResponse<Map> response = client.search(searchRequest, Map.class);
        // Extract `message` fields using Elasticsearch Java API
        messages = response.hits().hits().stream().map(hit -> {
            @SuppressWarnings("unchecked")
            Map<String, Object> source = hit.source();
            if (source != null && source.containsKey("message")) {
                return (String) source.get("message");
            }
            return null;
        }).filter(// Remove null values
        Objects::nonNull).collect(Collectors.toList());
        if (!messages.isEmpty()) {
            // Stop polling if data is found
            break;
        }
        // Wait for 1 second before retrying
        Thread.sleep(1000);
        retryCount++;
    }
    if (messages.isEmpty()) {
        throw new AssertionError("Elasticsearch validation failed: No messages found after polling.");
    }
    LOG.info("Extracted messages from Elasticsearch: {}", messages);
    // Create expected messages list
    List<String> expectedMessages = new ArrayList<>();
    expectedMessages.add(FIRST_EXPECTED_MESSAGE);
    expectedMessages.add(SECOND_EXPECTED_MESSAGE);
    // Validate messages against the expected messages
    if (new HashSet<>(messages).equals(new HashSet<>(expectedMessages))) {
        LOG.info("Elasticsearch contains all expected messages: {}", expectedMessages);
    } else {
        throw new AssertionError(String.format("Elasticsearch validation failed. Expected: %s, Found: %s", expectedMessages, messages));
    }
}

