@Test
public void testProjectRowFormatInfoWithProjection() {
    DataType dataType = ResolvedSchema.of(Column.physical("date", DataTypes.DATE()), Column.physical("score", DataTypes.FLOAT())).toPhysicalRowDataType();
    RowFormatInfo rowFormatInfo = new RowFormatInfo(new String[] { "student_name", "score", "date" }, new FormatInfo[] { StringFormatInfo.INSTANCE, FloatFormatInfo.INSTANCE, new DateFormatInfo("yyyy-MM-dd") });
    RowFormatInfo projectedRowFormatInfo = TableFormatForRowDataUtils.projectRowFormatInfo(rowFormatInfo, dataType);
    assertEquals(2, projectedRowFormatInfo.getFieldNames().length);
    assertEquals(2, projectedRowFormatInfo.getFieldFormatInfos().length);
    assertEquals("date", projectedRowFormatInfo.getFieldNames()[0]);
    assertEquals("score", projectedRowFormatInfo.getFieldNames()[1]);
    assertEquals(new DateFormatInfo("yyyy-MM-dd"), projectedRowFormatInfo.getFieldFormatInfos()[0]);
    assertEquals(FloatFormatInfo.INSTANCE, projectedRowFormatInfo.getFieldFormatInfos()[1]);
}

