    Consumer<KvRowDataDeserializationSchema.Builder> config = builder -> builder.setEscapeCharacter('\\').setQuoteCharacter('\"');
    GenericRowData rowData1 = new GenericRowData(4);
    rowData1.setField(0, 10);
