@Test
public void testSplitNormal() {
    List<Map<String, String>> list = splitKv("f1=a\nf1=b", '&', '=', '\\', '\"', '\n', true);
    List<Map<String, String>> expectedList = new ArrayList<>();
    expectedList.add(new HashMap<String, String>() {

        {
            put("f1", "a");
        }
    });
    expectedList.add(new HashMap<String, String>() {

        {
            put("f1", "b");
        }
    });
    assertEquals(list, expectedList);
    assertEquals(new HashMap<String, String>() {

        {
            put("f1", "a");
            put("f2", "b");
            put("f3", "c");
        }
    }, splitKv("f1=a&f2=b&f3=c", '&', '=', null, null));
    assertEquals(new HashMap<String, String>() {

        {
            put("f1", "");
            put("f2", "b");
            put("f3", "c");
        }
    }, splitKv("f1=&f2=b&f3=c", '&', '=', null, null));
    assertEquals(new HashMap<String, String>() {

        {
            put("f1", "a");
            put("f2", "b");
            put("f3", "");
        }
    }, splitKv("f1=a&f2=b&f3=", '&', '=', null, null));
    assertEquals(new HashMap<String, String>() {

        {
            put("=f1", "a");
            put("f2", "b");
            put("f3", "c");
        }
    }, splitKv("\\=f1=a&f2=b&f3=c", '&', '=', '\\', null));
    assertEquals(new HashMap<String, String>() {

        {
            put("&f1", "a");
            put("f2", "b");
            put("f3", "c");
        }
    }, splitKv("\\&f1=a&f2=b&f3=c", '&', '=', '\\', null));
    assertEquals(new HashMap<String, String>() {

        {
            put("&f1", "a");
            put("f2", "b");
            put("f3", "c");
        }
    }, splitKv("\"&f1\"=a&f2=b&f3=c", '&', '=', '\\', '\"'));
    assertEquals(new HashMap<String, String>() {

        {
            put("f1", "a&");
            put("f2", "b");
            put("f3", "c");
        }
    }, splitKv("f1=a\\&&f2=b&f3=c", '&', '=', '\\', null));
    assertEquals(new HashMap<String, String>() {

        {
            put("f1", "a\\");
            put("f2", "b");
            put("f3", "c");
        }
    }, splitKv("f1=a\\\\&f2=b&f3=c", '&', '=', '\\', null));
    assertEquals(new HashMap<String, String>() {

        {
            put("f1", "a&f2=b");
            put("f3", "c");
            put("f4", "d");
        }
    }, splitKv("f1=a\"&f2=\"b&f3=c&f4=d", '&', '=', '\\', '\"'));
    assertEquals(new HashMap<String, String>() {

        {
            put("f1", "atest\\test");
            put("f2", "b");
            put("f3", "c");
        }
    }, splitKv("f1=a\"test\\test\"&f2=b&f3=c", '&', '=', '\\', '\"'));
    assertEquals(new HashMap<String, String>() {

        {
            put("f1", "a");
            put("f2", "\"b");
            put("f3", "c\"");
            put("f4", "d");
        }
    }, splitKv("f1=a&f2=\\\"b&f3=c\\\"&f4=d", '&', '=', '\\', '\"'));
    assertEquals(new HashMap<String, String>() {

        {
            put("f1", "b");
        }
    }, splitKv("f1=a&f1=b", '&', '=', '\\', '\"'));
    assertEquals(new HashMap<String, String>() {

        {
            put("", "a");
            put("f", "");
        }
    }, splitKv("=a&f=", '&', '=', '\\', '\"'));
}

@Test
public void testSplitNormalWithoutEscape() {
    List<Map<String, String>> list = splitKv("f1=a\nf1=b", '&', '=', '\\', '\"', '\n', false);
    List<Map<String, String>> expectedList = new ArrayList<>();
    expectedList.add(new HashMap<String, String>() {

        {
            put("f1", "a");
        }
    });
    expectedList.add(new HashMap<String, String>() {

        {
            put("f1", "b");
        }
    });
    assertEquals(list, expectedList);
    ArrayList expectedListMap = new ArrayList<HashMap<String, String>>();
    HashMap expectedMap = new HashMap<String, String>();
    expectedMap.put("\\=f1", "a");
    expectedMap.put("f2", "b");
    expectedMap.put("f3", "c");
    expectedListMap.add(expectedMap);
    assertEquals(expectedListMap, splitKv("\\=f1=a&f2=b&f3=c", '&', '=', '\\', null, null, false));
    expectedMap.clear();
    expectedMap.put("\\&f1", "a");
    expectedMap.put("f2", "b");
    expectedMap.put("f3", "c");
    assertEquals(expectedListMap, splitKv("\\&f1=a&f2=b&f3=c", '&', '=', '\\', null, null, false));
    expectedMap.clear();
    expectedMap.put("&f1", "a");
    expectedMap.put("f2", "b");
    expectedMap.put("f3", "c");
    assertEquals(expectedListMap, splitKv("\"&f1\"=a&f2=b&f3=c", '&', '=', '\\', '\"', null, false));
    expectedMap.clear();
    expectedMap.put("f1", "a\\&");
    expectedMap.put("f2", "b");
    expectedMap.put("f3", "c");
    assertEquals(expectedListMap, splitKv("f1=a\\&&f2=b&f3=c", '&', '=', '\\', null, null, false));
    expectedMap.clear();
    expectedMap.put("f1", "a\\\\");
    expectedMap.put("f2", "b");
    expectedMap.put("f3", "c");
    assertEquals(expectedListMap, splitKv("f1=a\\\\&f2=b&f3=c", '&', '=', '\\', null, null, false));
    expectedMap.clear();
    expectedMap.put("f1", "a&f2=b");
    expectedMap.put("f3", "c");
    expectedMap.put("f4", "d");
    assertEquals(expectedListMap, splitKv("f1=a\"&f2=\"b&f3=c&f4=d", '&', '=', '\\', '\"', null, false));
    expectedMap.clear();
    expectedMap.put("f1", "atest\\test");
    expectedMap.put("f2", "b");
    expectedMap.put("f3", "c");
    assertEquals(expectedListMap, splitKv("f1=a\"test\\test\"&f2=b&f3=c", '&', '=', '\\', '\"', null, false));
    expectedMap.clear();
    expectedMap.put("f1", "a");
    expectedMap.put("f2", "\\\"b");
    expectedMap.put("f3", "c\\\"");
    expectedMap.put("f4", "d");
    assertEquals(expectedListMap, splitKv("f1=a&f2=\\\"b&f3=c\\\"&f4=d", '&', '=', '\\', '\"', null, false));
    expectedMap.clear();
    expectedMap.put("", "a");
    expectedMap.put("f", "");
    HashMap expectedMap2 = new HashMap<String, String>();
    expectedMap2.put("c", "dd");
    expectedListMap.add(expectedMap2);
    assertEquals(expectedListMap, splitKv("=a&f=\nc=d\\d", '&', '=', '\\', '\"', '\n', true));
}

